import fs from 'node:fs';
import path from 'node:path';
const root=path.resolve(process.argv[2]);
const entries=JSON.parse(fs.readFileSync(path.join(root,'entries.json'),'utf8'));
const expected='Unknown item kinds must be returned for review.\n';
const keys=Object.keys(entries).sort();
const names=Object.values(entries);
const resolves=names.every(name=>typeof name==='string' && path.basename(name)===name && fs.existsSync(path.join(root,name)));
const definitions=fs.readdirSync(root).filter(name=>name.endsWith('-policy.txt') || name==='policy.txt');
const result={entriesPreserved:JSON.stringify(keys)===JSON.stringify(['export','import']),referencesResolve:resolves,policyPreserved:resolves && names.every(name=>fs.readFileSync(path.join(root,name),'utf8')===expected),oneAuthority:definitions.length===1 && new Set(names).size===1};
console.log(JSON.stringify(result));
process.exitCode=Object.values(result).every(Boolean)?0:1;
